import React, { useState } from 'react';
import Blobs from '../components/Blobs';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak, onAnalysisDone }) {
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true);
    setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = {
        id: Date.now(),
        user_text: text,
        trap_label: ai.trap_label,
        trap_icon: ai.trap_icon,
        description: ai.description,
        reframe: ai.reframe,
        second_trap: ai.second_trap,
        exercise_text: ai.exercise_text,
        date: new Date().toISOString(),
      };
      addThought(entry);
      setResult(entry);
    } catch (e) {
      setError('Kunde inte analysera just nu. Försök igen.');
    }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={() => { setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs variant="default" />
      <div style={{ position:'relative', zIndex:1, padding:'100px 24px 48px', maxWidth:560, margin:'0 auto' }}>

        {/* Big editorial heading */}
        <div style={{ marginBottom:64, animation:'fadeUp .8s cubic-bezier(0.16,1,0.3,1) both' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', marginBottom:20 }}>
            Mental hälsa · KBT-baserad
          </p>
          <h1 style={{ fontSize:'clamp(52px,12vw,88px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#fff', marginBottom:24 }}>
            BRYT<br/>
            <span style={{ color:'rgba(255,255,255,0.22)' }}>TANKE-<br/>SPIRALEN</span>
          </h1>
          <p style={{ fontSize:15, color:'rgba(255,255,255,0.45)', lineHeight:1.8, fontWeight:300, maxWidth:400 }}>
            Skriv ner vad du tänker. AI:n hjälper dig förstå vad som händer — objektivt, utan att säga det du vill höra.
          </p>
        </div>

        {streak > 0 && (
          <div style={{ display:'inline-flex', alignItems:'center', gap:8, padding:'7px 14px', borderRadius:100, border:'1px solid rgba(255,255,255,0.1)', background:'rgba(255,255,255,0.04)', marginBottom:32, fontSize:12, color:'rgba(255,255,255,0.55)' }}>
            🔥 {streak} dag{streak > 1 ? 'ar' : ''} i rad
          </div>
        )}

        {/* Thought input card */}
        <div style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.08)', borderRadius:20, padding:'28px', backdropFilter:'blur(20px)', animation:'fadeUp .9s .1s cubic-bezier(0.16,1,0.3,1) both', marginBottom:16 }}>
          <p style={{ fontSize:11, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', marginBottom:16, fontFamily:'DM Mono,monospace' }}>Vad snurrar i huvudet just nu?</p>
          <textarea
            value={text}
            onChange={e => setText(e.target.value)}
            maxLength={1000}
            placeholder="Skriv fritt... t.ex. 'Jag är säker på att alla tyckte jag var konstig på mötet idag'"
            style={{
              width:'100%', minHeight:140, background:'transparent', border:'none',
              color:'#fff', fontSize:15, fontWeight:300, lineHeight:1.7,
              resize:'none', outline:'none',
              placeholder: 'rgba(255,255,255,0.2)',
            }}
          />
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginTop:16, paddingTop:16, borderTop:'1px solid rgba(255,255,255,0.06)' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.2)' }}>{text.length}/1000</span>
            <button onClick={handleSubmit} disabled={!text.trim() || loading}
              style={{ padding:'11px 24px', borderRadius:100, background: text.trim() && !loading ? '#fff' : 'rgba(255,255,255,0.15)', color: text.trim() && !loading ? '#0e0e12' : 'rgba(255,255,255,0.3)', fontSize:13, fontWeight:600, transition:'all .25s', opacity: loading ? 0.7 : 1 }}>
              {loading ? (
                <span style={{ display:'flex', alignItems:'center', gap:8 }}>
                  <span style={{ width:12, height:12, border:'2px solid rgba(0,0,0,0.3)', borderTopColor:'#000', borderRadius:'50%', display:'inline-block', animation:'spin .7s linear infinite' }} />
                  Analyserar...
                </span>
              ) : 'Analysera →'}
            </button>
          </div>
          {error && <p style={{ color:'rgba(255,100,100,0.8)', fontSize:12, marginTop:12 }}>{error}</p>}
        </div>

        {/* Breathing shortcut */}
        <button onClick={() => setPage('breathing')}
          style={{ width:'100%', padding:'18px 24px', background:'rgba(255,255,255,0.03)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, display:'flex', alignItems:'center', justifyContent:'space-between', color:'rgba(255,255,255,0.5)', fontSize:13, transition:'all .25s', animation:'fadeUp .9s .2s cubic-bezier(0.16,1,0.3,1) both' }}
          onMouseEnter={e=>{e.currentTarget.style.background='rgba(255,255,255,0.06)';e.currentTarget.style.color='#fff'}}
          onMouseLeave={e=>{e.currentTarget.style.background='rgba(255,255,255,0.03)';e.currentTarget.style.color='rgba(255,255,255,0.5)'}}>
          <span style={{ display:'flex', alignItems:'center', gap:10 }}>
            <span style={{ fontSize:18 }}>🫁</span>
            <span>Snabb andningsövning  —  4-7-8 tekniken</span>
          </span>
          <span>→</span>
        </button>
      </div>
    </div>
  );
}

