      <Blobs variant="warm" />
      <div style={{ position:'relative', zIndex:1, padding:'100px 24px 48px', maxWidth:560, margin:'0 auto', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

